import json
from itertools import permutations

def solve_puzzle():
    houses = [1, 2, 3]  # positions from left to right

    # Attributes and their values
    Names = ["Arnold", "Eric", "Peter"]
    Flowers = ["carnations", "lilies", "daffodils"]
    Hairs = ["black", "brown", "blonde"]
    Sports = ["soccer", "basketball", "tennis"]
    Styles = ["colonial", "ranch", "victorian"]
    Pets = ["fish", "dog", "cat"]

    solutions = []

    for hair in permutations(Hairs):
        # 2. The person who has blonde hair is in the second house.
        if hair[1] != "blonde":
            continue

        for flower in permutations(Flowers):
            # 3. The person who loves a bouquet of daffodils is the person who has blonde hair.
            if flower[hair.index("blonde")] != "daffodils":
                continue
            # 7. The person who loves a carnations arrangement is directly left of the person who has blonde hair.
            if flower.index("carnations") + 1 != hair.index("blonde"):
                continue

            for sport in permutations(Sports):
                # 8. The person who loves soccer is in the third house.
                if sport[2] != "soccer":
                    continue

                for pet in permutations(Pets):
                    # 1. The person who has a cat is the person who loves soccer.
                    if pet[sport.index("soccer")] != "cat":
                        continue
                    # 6. The person who owns a dog is the person who loves basketball.
                    if pet[sport.index("basketball")] != "dog":
                        continue

                    for style in permutations(Styles):
                        # 10. The person living in a colonial-style house is in the third house.
                        if style[2] != "colonial":
                            continue

                        for name in permutations(Names):
                            # 4. Peter is the person who loves basketball.
                            if name[sport.index("basketball")] != "Peter":
                                continue
                            # 5. Arnold is directly left of the person in a ranch-style home.
                            if name.index("Arnold") + 1 != style.index("ranch"):
                                continue
                            # 9. Arnold is somewhere to the left of the person who has black hair.
                            if not (name.index("Arnold") < hair.index("black")):
                                continue

                            # All constraints satisfied, build the solution mapping per house
                            for i in range(3):
                                pass  # placeholder, nothing needed here

                            solutions.append({
                                "House": ["1", "2", "3"],
                                "Name": list(name),
                                "favorite flower": list(flower),
                                "hair colors": list(hair),
                                "favorite sports": list(sport),
                                "style of house": list(style),
                                "type of pet": list(pet),
                            })

    return solutions

def format_solution(sol):
    header = ["House", "Name", "favorite flower", "hair colors", "favorite sports", "style of house", "type of pet"]
    rows = []
    # Houses are in order 1,2,3
    for i in range(3):
        row = [
            sol["House"][i],
            sol["Name"][i],
            sol["favorite flower"][i],
            sol["hair colors"][i],
            sol["favorite sports"][i],
            sol["style of house"][i],
            sol["type of pet"][i],
        ]
        rows.append(row)
    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

def main():
    solutions = solve_puzzle()
    if not solutions:
        output = {"error": "No solution found"}
    else:
        # Assuming unique solution; take the first
        output = format_solution(solutions[0])
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
